const root = document.querySelector('#game');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#161b43');
scene.fog = new THREE.FogExp2('#1b2250', 0.035);
const camera = new THREE.PerspectiveCamera(42, innerWidth / innerHeight, .1, 100);
camera.position.set(0, .35, 10.8);
camera.lookAt(0, .2, 0);
const renderer = new THREE.WebGLRenderer({antialias:true, alpha:false, powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
root.appendChild(renderer.domElement);

scene.add(new THREE.HemisphereLight(0xb9d8ff, 0x46356f, 2.0));
const keyLight = new THREE.DirectionalLight(0xffdfec, 3.1); keyLight.position.set(-3,6,6); scene.add(keyLight);
const rimLight = new THREE.PointLight(0x55eaff, 25, 16); rimLight.position.set(3,2,3); scene.add(rimLight);
const pinkLight = new THREE.PointLight(0xff71c8, 20, 12); pinkLight.position.set(-3,-.4,2); scene.add(pinkLight);
const mat=(color,roughness=.7,metalness=0,emissive=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness,emissive:color,emissiveIntensity:emissive});
const mats={cloud:mat('#a8b7ef',.94),cloudHi:mat('#d2dcff',.88),island:mat('#434b91'),gold:mat('#ffc777',.35,.55,.12),dress:mat('#ad66d9',.48,.08,.2),dress2:mat('#e98bd8',.5,0,.1),skin:mat('#ffd0b5',.7),hair:mat('#302452',.42,0,.18),hairHi:mat('#7548a5',.4,0,.22),boot:mat('#f08dbd',.5,.1,.08),white:mat('#fff2ed',.28),eye:mat('#47d8ee',.2,0,.25),dark:mat('#2a264c'),rope:mat('#74f3ff',.3,.25,.8),ropeOff:mat('#7f729c',.48,.15,.06),wing:mat('#74eaff',.28,.2,.4)};
function ball(parent,x,y,z,sx,sy,sz,material){const m=new THREE.Mesh(new THREE.SphereGeometry(1,24,18),material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);parent.add(m);return m;}
function box(parent,x,y,z,sx,sy,sz,material,r=.1){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);parent.add(m);return m;}
function rod(parent,a,b,r,material,segments=12){const dir=new THREE.Vector3().subVectors(b,a);const mesh=new THREE.Mesh(new THREE.CylinderGeometry(r,r,dir.length(),segments),material);mesh.position.copy(a).add(b).multiplyScalar(.5);mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),dir.normalize());parent.add(mesh);return mesh;}
function makeCloud(parent,x,y,z,s=1){const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);ball(g,0,0,0,.85*s,.35*s,.43*s,mats.cloud);ball(g,-.45*s,.11*s,.01,.46*s,.4*s,.4*s,mats.cloudHi);ball(g,.35*s,.13*s,.03,.56*s,.48*s,.46*s,mats.cloudHi);ball(g,.77*s,-.02*s,.03,.42*s,.3*s,.34*s,mats.cloud);return g;}
// Soft sky, distant cloud banks, and floating island stage.
const moon=ball(scene,3.55,2.4,-5,.72,.72,.15,mat('#fff0c1',.3,0,.8));
for(let i=0;i<95;i++){const a=new THREE.Mesh(new THREE.SphereGeometry(.018+Math.random()*.025,8,6),new THREE.MeshBasicMaterial({color:i%4===0?'#9cf6ff':'#fff4d8',transparent:true,opacity:.35+Math.random()*.55}));a.position.set((Math.random()-.5)*16,Math.random()*9-3,-3-Math.random()*8);scene.add(a);}
for(let i=0;i<8;i++){makeCloud(scene,(i-3.5)*2.1,-1.7+(i%3)*.26,-3.3-Math.random()*1.7,.75+Math.random()*.65);}
const island=new THREE.Group();scene.add(island);
const plateau=new THREE.Mesh(new THREE.CylinderGeometry(2.2,1.35,.72,9,1),mats.island);plateau.position.set(0,-2.14,-.2);plateau.rotation.y=.12;island.add(plateau);
const top=new THREE.Mesh(new THREE.CylinderGeometry(2.2,2.2,.1,9),mat('#6a75b5'));top.position.set(0,-1.75,-.2);island.add(top);
for(let i=0;i<7;i++){const c=ball(island,(Math.random()-.5)*3.1,-1.8+Math.random()*.24,.15+Math.random()*.25,.3,.2,.3,i%2?mats.cloudHi:mats.cloud);}
for(let i=0;i<4;i++){const crystal=new THREE.Mesh(new THREE.OctahedronGeometry(.2+Math.random()*.15),i%2?mats.wing:mats.gold);crystal.position.set(-1.5+i*.9,-1.56,.32);crystal.rotation.y=i;island.add(crystal);}
makeCloud(scene,-3.4,-2.8,1,.65);makeCloud(scene,3.3,-2.5,-.4,.8);
// The rescued sky courier is an original, friendly low-poly 3D character.
const hero=new THREE.Group();hero.position.set(0,-.58,0);scene.add(hero);
const torso=ball(hero,0,-.15,0,.39,.61,.27,mats.dress);
const skirt=new THREE.Mesh(new THREE.ConeGeometry(.68,.57,9),mats.dress2);skirt.position.y=-.52;skirt.rotation.y=.18;hero.add(skirt);
const collar=ball(hero,0,.35,0,.29,.12,.24,mats.white);
const head=ball(hero,0,.82,.02,.47,.53,.42,mats.skin);
// Hair cap and long side locks.
ball(hero,0,1.13,-.04,.5,.34,.45,mats.hair);
const bang= new THREE.Mesh(new THREE.ConeGeometry(.23,.52,5),mats.hairHi);bang.position.set(-.18,.95,.39);bang.rotation.z=.2;bang.rotation.x=-.25;hero.add(bang);
const bang2=new THREE.Mesh(new THREE.ConeGeometry(.2,.43,5),mats.hair);bang2.position.set(.13,1.01,.4);bang2.rotation.z=-.22;bang2.rotation.x=-.2;hero.add(bang2);
for(const side of [-1,1]){ball(hero,side*.4,.47,-.02,.16,.58,.17,mats.hair);ball(hero,side*.44,-.01,.02,.12,.4,.13,mats.hairHi);}
// Bright eyes, blush, and a tiny smile.
for(const s of [-1,1]){ball(hero,s*.17,.83,.393,.065,.09,.035,mats.eye);ball(hero,s*.17,.84,.424,.024,.044,.014,mats.dark);ball(hero,s*.28,.68,.375,.075,.025,.02,mat('#ff9bb4',.8,0,.1));}
const smile= new THREE.Mesh(new THREE.TorusGeometry(.065,.012,6,14,Math.PI),mats.dress2);smile.position.set(0,.66,.42);smile.rotation.z=Math.PI;hero.add(smile);
// Arms out in a calm floating pose; boots and decorative harness are at the waist, never the neck.
for(const s of [-1,1]){rod(hero,new THREE.Vector3(s*.28,.13,.01),new THREE.Vector3(s*.64,-.08,.04),.13,mats.skin);ball(hero,s*.68,-.08,.04,.14,.14,.14,mats.skin);rod(hero,new THREE.Vector3(s*.22,-.65,0),new THREE.Vector3(s*.25,-1.12,.02),.12,mats.skin);ball(hero,s*.25,-1.18,.12,.22,.14,.3,mats.boot);}
const belt= new THREE.Mesh(new THREE.TorusGeometry(.33,.045,8,28),mats.gold);belt.position.set(0,-.18,.08);belt.rotation.x=Math.PI/2;hero.add(belt);
const starPin=new THREE.Mesh(new THREE.OctahedronGeometry(.12),mats.gold);starPin.position.set(.03,-.12,.34);hero.add(starPin);
const cape= new THREE.Mesh(new THREE.ConeGeometry(.43,.92,6),mats.hairHi);cape.position.set(0,-.28,-.35);cape.rotation.x=-.1;hero.add(cape);
// Tether bundle with bright, selectable target segments and a sparkling anchor.
const tetherGroup=new THREE.Group();scene.add(tetherGroup);
const targetGroup=new THREE.Group();scene.add(targetGroup);
const raycaster=new THREE.Raycaster();raycaster.params.Line.threshold=.18;
const pointer=new THREE.Vector2();const aimEl=document.querySelector('#aim');
let level=1, health=100, active=false, rescued=false, selected=null, lastShot=0, soundOn=false, audioCtx=null, tethers=[];
const levelEl=document.querySelector('#level'),fill=document.querySelector('#healthFill'),healthText=document.querySelector('#healthText'),statusEl=document.querySelector('#status'),toast=document.querySelector('#toast');
function makeTethers(){tetherGroup.clear();targetGroup.clear();tethers=[];const count=Math.min(1+Math.floor((level-1)/2),6);for(let i=0;i<count;i++){const x=(i-(count-1)/2)*.28;const top=new THREE.Vector3(x*.25,2.72,-.03);const end=new THREE.Vector3(x,-.05,.08);const geo=new THREE.CylinderGeometry(.055,.075,top.distanceTo(end),10);const rope=new THREE.Mesh(geo,mats.rope);rope.position.copy(top).add(end).multiplyScalar(.5);rope.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),new THREE.Vector3().subVectors(end,top).normalize());rope.userData={index:i};targetGroup.add(rope);const core=new THREE.Mesh(new THREE.CylinderGeometry(.018,.022,top.distanceTo(end),8),new THREE.MeshBasicMaterial({color:0xc9fcff}));core.position.copy(rope.position);core.quaternion.copy(rope.quaternion);tetherGroup.add(core);const a=new THREE.Mesh(new THREE.OctahedronGeometry(.15),mats.gold);a.position.copy(top);a.rotation.z=Math.PI/4;tetherGroup.add(a);const halo=new THREE.Mesh(new THREE.TorusGeometry(.12,.018,6,16),mats.wing);halo.position.copy(top);tetherGroup.add(halo);tethers.push({rope,core,anchor:a,halo,cut:false});}}
function setLevel(n){level=n;levelEl.textContent=String(level).padStart(2,'0');health=100;rescued=false;active=true;document.querySelector('#result').style.display='none';makeTethers();statusEl.textContent=`${tethers.length} enchanted tether${tethers.length>1?'s':''} • Free them before the signal fades!`;}
function showToast(text){toast.textContent=text;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),900);}
function endGame(success){active=false;rescued=success;const overlay=document.querySelector('#result');document.querySelector('#resultEmoji').textContent=success?'💖':'🌙';document.querySelector('#resultTitle').textContent=success?'Rescue complete!':'Signal needs a recharge';document.querySelector('#resultText').textContent=success?'You brought the sky courier safely back to the island. Ready for the next mission?':'The rescue signal faded, but the courier is safe in a sky bubble. Recharge and try again!';document.querySelector('#next').textContent=success?'NEXT MISSION':'TRY AGAIN';overlay.style.display='flex';}
function playTone(freq=520,duration=.09,type='sine'){if(!soundOn)return;try{audioCtx??=new AudioContext();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch{}}
function nearestTether(clientX,clientY){const rect=renderer.domElement.getBoundingClientRect();pointer.x=((clientX-rect.left)/rect.width)*2-1;pointer.y=-((clientY-rect.top)/rect.height)*2+1;raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(targetGroup.children,false);if(hits.length)return tethers[hits[0].object.userData.index];let best=null,bestD=Infinity;for(const t of tethers){if(t.cut)continue;const p=t.rope.position.clone().project(camera);const sx=rect.left+(p.x+1)*rect.width/2,sy=rect.top+(1-p.y)*rect.height/2;const d=Math.hypot(sx-clientX,sy-clientY);if(d<bestD){bestD=d;best=t;}}return bestD<Math.max(52,rect.width*.12)?best:null;}
function aimAt(x,y){const rect=renderer.domElement.getBoundingClientRect();const target=nearestTether(x,y);selected=target;aimEl.style.display=target?'block':'none';if(target){const p=target.rope.position.clone().project(camera);aimEl.style.left=`${rect.left+(p.x+1)*rect.width/2}px`;aimEl.style.top=`${rect.top+(1-p.y)*rect.height/2}px`;}}
function fire(target=selected){if(!active||!target){if(active)showToast('AIM AT A GLOWING TETHER');return;}const now=performance.now();if(now-lastShot<250)return;lastShot=now;if(target.cut){target=tethers.find(t=>!t.cut);if(!target)return;}target.cut=true;targetGroup.remove(target.rope);tetherGroup.remove(target.core,target.anchor,target.halo);playTone(720,.12,'triangle');showToast('TETHER RELEASED!');hero.rotation.z+=(Math.random()-.5)*.1;const remaining=tethers.filter(t=>!t.cut).length;if(remaining===0){hero.position.y-=.03;setTimeout(()=>{if(!active)return;showToast('HERO SAFE! ✨');playTone(930,.22,'sine');setTimeout(()=>endGame(true),650);},150);}else statusEl.textContent=`${remaining} tether${remaining>1?'s':''} left • Nice aim!`;selected=null;aimEl.style.display='none';}
function shootAt(x,y){const target=nearestTether(x,y);if(target){aimAt(x,y);fire(target);}else{aimEl.style.display='none';}}
renderer.domElement.addEventListener('pointermove',e=>{aimAt(e.clientX,e.clientY);});renderer.domElement.addEventListener('pointerleave',()=>{aimEl.style.display='none';});renderer.domElement.addEventListener('pointerdown',e=>{if(!active)return;e.preventDefault();shootAt(e.clientX,e.clientY);});
document.querySelector('#fire').addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();fire(selected||tethers.find(t=>!t.cut));});
window.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();fire(selected||tethers.find(t=>!t.cut));}});
document.querySelector('#start').addEventListener('click',()=>{document.querySelector('#intro').style.display='none';setLevel(1);});
document.querySelector('#next').addEventListener('click',()=>{if(rescued)setLevel(level+1);else setLevel(level);});
document.querySelector('#sound').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';playTone(560,.08);});
function resize(){camera.aspect=innerWidth/innerHeight;camera.position.z=innerWidth<600?12.4:10.8;camera.position.y=innerHeight<480?-.05:.35;camera.lookAt(0,.2,0);camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));}
window.addEventListener('resize',resize);window.addEventListener('orientationchange',()=>setTimeout(resize,150));
let last=performance.now();function animate(now){requestAnimationFrame(animate);const dt=Math.min(.05,(now-last)/1000);last=now;const time=now*.001;hero.position.y=-.58+Math.sin(time*1.35)*.065;hero.rotation.y=Math.sin(time*.7)*.09;hero.rotation.z=Math.sin(time*1.1)*.025;cape.rotation.z=Math.sin(time*2)*.1;island.rotation.y=Math.sin(time*.12)*.025;for(let i=0;i<tethers.length;i++){const t=tethers[i];if(!t.cut){t.halo.rotation.z=time*1.3+i;t.anchor.rotation.y=time*1.7;const pulse=.85+Math.sin(time*4+i)*.15;t.rope.material.emissiveIntensity=pulse;t.rope.scale.x=1;}}
if(active){health=Math.max(0,health-dt*(2.5+level*.9));fill.style.width=`${health}%`;healthText.textContent=`${Math.ceil(health)}%`;if(health<30)fill.style.background='linear-gradient(90deg,#ff4f85,#ff936c)';else fill.style.background='linear-gradient(90deg,#ff739f,#ffb97a)';if(health<=0){statusEl.textContent='Rescue signal faded';endGame(false);}}
renderer.render(scene,camera);}
requestAnimationFrame(animate);

